# Worker {N} Task: {TASK_NAME}

## Context
{PROJECT_CONTEXT}

## Your Task
{TASK_DESCRIPTION}

## Files You OWN (create/modify freely)
{OWNED_FILES_LIST}

## Files You CAN READ (do NOT modify)
{READ_ONLY_FILES_LIST}

## Success Criteria
{SUCCESS_CRITERIA_CHECKLIST}

## Implementation Notes
{ADDITIONAL_NOTES}

#!/bin/bash
# Swarm: {SWARM_NAME} — {N} workers
# Created: {DATE}

PROJECT_DIR="{PROJECT_PATH}"
SWARM_BASE="/tmp/{PROJECT_NAME}-swarm"
TIMESTAMP=$(date +%s)

mkdir -p $SWARM_BASE
cd $PROJECT_DIR

# Ensure clean starting point
git fetch origin && git checkout main && git pull origin main

# Create worktrees
{WORKTREE_CREATION_COMMANDS}

# Setup tmux session
tmux new-session -d -s {SWARM_NAME}
{TMUX_WINDOW_CREATION_COMMANDS}

# Navigate workers to their worktrees
{WORKER_NAVIGATION_COMMANDS}

# Attach to monitor
tmux select-window -t {SWARM_NAME}:orchestrator
tmux attach -t {SWARM_NAME}

echo 'Swarm {SWARM_NAME} deployed. Workers: {N}'
